nextflow_process {

    name "Test Process LAST_MAFCONVERT"
    script "../main.nf"
    process "LAST_MAFCONVERT"
    config "./nextflow.config"

    tag "modules"
    tag "modules_nfcore"
    tag "last"
    tag "last/mafconvert"

    test("sarscov2 - psl") {

        when {
            process {
                """
                input[0] = [
                    [ id:'contigs.genome' ], // meta map
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/alignment/last/contigs.genome.maf.gz', checkIfExists: true),
                    'psl'
                ]
                input[1] = [[],[],[],[],[],[]]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }

    }

    test("sarscov2 - sam") {

        when {
            process {
                """
                input[0] = [
                    [ id:'contigs.genome' ], // meta map
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/alignment/last/contigs.genome.maf.gz', checkIfExists: true),
                    'sam'
                ]
                input[1] = [[],[],[],[],[],[]]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }

    }

    test("sarscov2 - bam") {

        when {
            process {
                """
                input[0] = [
                    [ id:'contigs.genome' ], // meta map
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/alignment/last/contigs.genome.maf.gz', checkIfExists: true),
                    'bam'
                ]
                input[1] = [[],[],[],[],[],[]]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(
                    process.out.alignment.collect { bam(it[1]).getReadsMD5() },
                    process.out.findAll { key, val -> key.startsWith('versions') }
                ).match() }
            )
        }

    }

    test("sarscov2 - bcf") {

        when {
            process {
                """
                input[0] = [
                    [ id:'contigs.genome' ], // meta map
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/alignment/last/contigs.genome.maf.gz', checkIfExists: true),
                    'bcf'
                ]
                input[1] = [
                    [ id:'contigs.genome' ], // meta map
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta',     checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta.fai', checkIfExists: true),
                    [],
                    [],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.dict', checkIfExists: true)
                ]
                """
            }
        }
        then {
            assertAll(
                { assert process.success },
                { assert process.out.alignment[0][1].endsWith('.bcf') },
                { assert path(process.out.alignment[0][1]).size() > 0 },
                { assert snapshot(
                    process.out.findAll { key, val -> key.startsWith("versions") }
                ).match() }
            )
        }

    }

    test("sarscov2 - cram") {

        when {
            process {
                """
                input[0] = [
                    [ id:'contigs.genome' ], // meta map
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/alignment/last/contigs.genome.maf.gz', checkIfExists: true),
                    'cram'
                ]
                input[1] = [
                    [ id:'contigs.genome' ], // meta map
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta',     checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta.fai', checkIfExists: true),
                    [],
                    [],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.dict', checkIfExists: true)
                ]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(
                    process.out.alignment.collect { cram(it[1], it[1].replaceAll(/[^\/]+\.cram$/, 'genome.fasta')).getReadsMD5() },
                    process.out.findAll { key, val -> key.startsWith('versions') }
                ).match() }
            )
        }

    }

    test("sarscov2 - gff") {

        when {
            process {
                """
                input[0] = [
                    [ id:'contigs.genome' ], // meta map
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/alignment/last/contigs.genome.maf.gz', checkIfExists: true),
                    'gff'
                ]
                input[1] = [
                    [ id:'contigs.genome' ], // meta map
                    [],
                    [],
                    [],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.sizes', checkIfExists: true),
                    []
                ]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }

    }

    test("sarscov2 - psl - stub") {

        options "-stub"
        when {
            process {
                """
                input[0] = [
                    [ id:'contigs.genome' ], // meta map
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/alignment/last/contigs.genome.maf.gz', checkIfExists: true),
                    'psl'
                ]
                input[1] = [[],[],[],[],[],[]]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }

    }

}

